"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[1237],{5147(e){e.exports=JSON.parse('{"title":"Skills for Frontend","date":"2026-01-26","coverUrl":"/kudzu-based-bench/assets/notion/dcb492b1e161f3f0.png","html":"<h1 data-notion-block-id=\\"2f0e548d-8a8e-8060-ae81-f8b89a1917ab\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"2f1e548d-8a8e-802a-9437-d510a19df79c\\" id=\\"2f1e548d-8a8e-802a-9437-d510a19df79c\\">Skills for Frontend</h2><a href=\\"https://vercel.com/blog/introducing-react-best-practices\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/introducing-react-best-practices</a><a href=\\"https://www.callstack.com/blog/announcing-react-native-best-practices-for-ai-agents\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/announcing-react-native-best-practices-for-ai-agents</a><a href=\\"https://github.com/expo/skills\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/expo/skills</a><a href=\\"https://x.com/Remotion/status/2013626968386765291\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://x.com/Remotion/status/2013626968386765291</a><p data-notion-block-id=\\"2f1e548d-8a8e-8069-9441-fa436aa97fdf\\"><a href=\\"https://code.claude.com/docs/ko/skills\\">SKILL.md</a>\ub294 AI \ud65c\uc6a9\uc758 \uc0c8\ub85c\uc6b4 \ubd84\uae30\uac00 \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\uc5d0 \ub530\ub77c\uc11c, \uac01 \ud68c\uc0ac\ub4e4\uc774 react, react-native, expo, remotion\uc744 \uc798 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 SKILL.md \ubaa8\uc74c\uc9d1\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Claude code \ub9d0\uace0\ub3c4 \uc218\ub9ce\uc740 AI \ub3c4\uad6c\ub4e4\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\uc73c\ubbc0\ub85c \uc124\uce58\ud558\uace0 \uc798 \uc0ac\uc6a9\ud574\ubcf4\uc2dc\ub294\uac8c \uc88b\uc744 \ub4ef \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2f1e548d-8a8e-8088-afe7-d52c61e62c96\\" id=\\"2f1e548d-8a8e-8088-afe7-d52c61e62c96\\">Github PR \ud654\uba74 \uac1c\uc120\uae30</h2><a href=\\"https://wtbb.vercel.app/i-love-dogs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://wtbb.vercel.app/i-love-dogs</a><p data-notion-block-id=\\"2f0e548d-8a8e-80ed-a47c-c593ea5c0ad4\\">\uc608\uc804 Github\uc640 \ud604\uc7ac\uc758 Github\ub97c \ube44\uad50\ud558\uba74\uc11c PR \ud654\uba74\uc774 \uc5b4\ub5a4 \ubd80\ubd84\uc774 \ub098\uc544\uc84c\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc544\uc9c1 \uc544\uc26c\uc6b4 \ubd80\ubd84\uc774 \uc788\uc74c\uc744 \uc9da\uace0 \uac01 \ubb38\uc81c\ub9c8\ub2e4 \uc131\ub2a5\uacfc UX \ud2b8\ub808\uc774\ub4dc\uc624\ud504\ub97c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. React/Next.js/CSS\ub97c \ub118\ub098\ub4e4\uba70 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \ub300\uaddc\ubaa8 \ub9ac\uc2a4\ud2b8 \ub80c\ub354\ub9c1\uc744 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud574\uc57c \ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc0ac\uc6a9\uc790 UX\ub97c \uc704\ud574 \uc5b4\ub5bb\uac8c \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uc88b\uc740\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/2bde548d-8a8e-805b-83a0-e7a11b36e1f3#2bfe548d-8a8e-8057-becf-e03feb71cdad\\">Github \uc7ac\uad6c\uc131\ud558\uae30, RSC\uc640 CSS\ub85c</a>\uc758 \ud6c4\uc18d \uae00\uc774\ubbc0\ub85c \uc55e\uc758 \uae00\ub3c4 \ubcf4\uae30 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2f1e548d-8a8e-8016-8ae1-cff99b0d3122\\" id=\\"2f1e548d-8a8e-8016-8ae1-cff99b0d3122\\">E2E \ud14c\uc2a4\ud2b8 \ub300\uc2e0 Storybook\uc744 \uc0ac\uc6a9\ud558\ub77c.</h2><a href=\\"https://medium.com/preply-engineering/front-end-testing-at-preply-shifting-left-towards-component-testing-3e83c8608235\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/preply-engineering/front-end-testing-at-preply-shifting-left-towards-component-testing-3e83c8608235</a><p data-notion-block-id=\\"2f1e548d-8a8e-808d-928b-d5ff91eb3746\\">E2E \ud14c\uc2a4\ud2b8\uac00 \uc8fc\ub97c \uc774\ub8e8\ub358 \ud68c\uc0ac\uc5d0\uc11c \uc5b4\ub5bb\uac8c Storybook\uc744 \uc804\ud658\ud558\uace0 \ud300\uc5d0\uac8c \uc804\ud30c\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Storybook 8 \ubc84\uc804\uc5d0\uc11c e18e\ud300\uc758 \ub3c4\uc6c0\uc73c\ub85c <a href=\\"https://storybook.js.org/blog/storybook-bloat-fixed/\\">Storybook\uc758 \ubc88\ub4e4 \uc0ac\uc774\uc988 \ubb38\uc81c\ub3c4 \ud574\uacb0</a>\ub418\uc5c8\uc73c\ubbc0\ub85c, E2E \ud14c\uc2a4\ud2b8\ub97c \uba3c\uc800 \uace0\ub824\ud558\uae30 \ubcf4\ub2e4 MSW\uc640 Storybook\uc758 \uc870\ud569\uc73c\ub85c \uc2e4\uc81c \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \ud14c\uc2a4\ud2b8\ub97c Integration test\ub85c \uad6c\uc131\ud558\ub294 \uac83\uc744 \uace0\ub824\ud574\ubcf4\ub294 \uac83\ub3c4 \ub098\uc058\uc9c0 \uc54a\uc544\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2f1e548d-8a8e-80f7-be90-f556fc927565\\" id=\\"2f1e548d-8a8e-80f7-be90-f556fc927565\\">Turbopack\uc758 Incremental Caching\uc740 \uc5b4\ub5bb\uac8c \uc774\ub8e8\uc5b4\uc838\uc788\ub294\uac00</h2><a href=\\"https://nextjs.org/blog/turbopack-incremental-computation\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/turbopack-incremental-computation</a><p data-notion-block-id=\\"2f4e548d-8a8e-8041-b073-f9bd4579122e\\">Turbopack\uc5d0\uc11c \uc790\ub3d9 \uc99d\ubd84 \uce90\uc2f1\uc744 \uc704\ud574 \uc5b4\ub5bb\uac8c \uce90\uc2f1 \ubc29\uc2dd\uc744 \uad6c\uc131\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. web-infra-dev \ud300\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/17ee548d-8a8e-8045-8a26-f5dfa6d03856#182e548d-8a8e-80d5-a404-ce95e2facb12\\">\ubc88\ub4e4\ub7ec\ub97c \ube4c\ub4dc \uc2dc\uc2a4\ud15c \uad00\uc810\uc5d0\uc11c \ubd84\uc11d\ud558\uae30</a> \uae00\uc5d0\uc11c \ub354 \uc790\uc138\ud558\uac8c \ub2e4\ub978 \ubc88\ub4e4\ub7ec\ub294 \uc5b4\ub5a4 \ubc29\uc2dd\uc744 \ud0dd\ud588\ub294\uc9c0, \uadf8\ub9ac\uace0 Turbopack/Vite/Rspack\uc740 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc18c\uac1c\ud558\ubbc0\ub85c \ucd94\uac00\ub85c \ubcf4\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"2f0e548d-8a8e-80a7-8f16-d07f0172e2f6\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"2f3e548d-8a8e-80a8-99fd-f5a78308a372\\" id=\\"2f3e548d-8a8e-80a8-99fd-f5a78308a372\\">Optimistic update\uc5d0\ub294 <code>useOptimistic()</code>\ub9cc \ud544\uc694\ud55c\uac8c \uc544\ub2c8\ub2e4</h2><a href=\\"https://www.columkelly.com/blog/use-optimistic\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.columkelly.com/blog/use-optimistic</a><p data-notion-block-id=\\"2f3e548d-8a8e-8082-b4a2-dcea7aba0702\\">\uae30\uc874\uc758 Optimistic update\uc740 \uc5b4\ub5bb\uac8c \uc774\ub8e8\uc5b4\uc838 \uc654\ub294\uc9c0, React 19\uc5d0\uc11c \uc0c8\ub85c \ub098\uc628 hook\uc778 <code>useOptimistic()</code>\ub9cc\uc774 \uc774 \ubb38\uc81c\ub97c \uc644\uc804\ud788 \ud574\uacb0\ud558\uc9c0 \uc54a\uc74c\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2f4e548d-8a8e-80a7-a8cb-c857ef011ee1\\" id=\\"2f4e548d-8a8e-80a7-a8cb-c857ef011ee1\\">Array chaining\ub300\uc2e0, Iteration helper\ub97c \uc0ac\uc6a9\ud558\ub77c.</h2><a href=\\"https://allthingssmitty.com/2026/01/12/stop-turning-everything-into-arrays-and-do-less-work-instead/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://allthingssmitty.com/2026/01/12/stop-turning-everything-into-arrays-and-do-less-work-instead/</a><p data-notion-block-id=\\"2f4e548d-8a8e-805b-a06c-c625f78c36c8\\">Array chaining method\uc73c\ub85c \uc0c8\ub85c\uc6b4 array\ub97c \uacc4\uc18d \ub9cc\ub4e4\uae30\ubcf4\ub2e4\ub294 ES2025\uc5d0 \uc0c8\ub85c \ucd94\uac00\ub41c, \uadf8\ub9ac\uace0 \ucd5c\uc2e0 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ubaa8\ub450 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 Iteration helper\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \uad8c\uc7a5\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2f1e548d-8a8e-804e-97ec-c39a05d5e97e\\" id=\\"2f1e548d-8a8e-804e-97ec-c39a05d5e97e\\">asChild/Slot \ud328\ud134\uc758 \ud55c\uacc4\uc810, \uadf8\ub9ac\uace0 Base UI\uc758 \uc811\uadfc\ubc95</h2><a href=\\"https://boda.sh/blog/react-slot-aschild-pattern/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://boda.sh/blog/react-slot-aschild-pattern/</a><p data-notion-block-id=\\"2f1e548d-8a8e-801d-97d2-f58991d75009\\">Radix UI\uc5d0\uc11c \uad6c\ud604\ub41c asChild \ud328\ud134, Slot \ud328\ud134\uc774 \uc5b4\ub5a4 \ud55c\uacc4\uc810\uc774 \uc788\uace0, Base UI\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2f4e548d-8a8e-800c-b70a-eb787c20e4ea\\" id=\\"2f4e548d-8a8e-800c-b70a-eb787c20e4ea\\">Node.js AsyncLocalStorage\uc5d0\uc11c \uc624\ub958\uac00 \ubc1c\uc0dd\ud55c \uc774\uc720</h2><a href=\\"https://nodejs.org/en/blog/vulnerability/january-2026-dos-mitigation-async-hooks\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodejs.org/en/blog/vulnerability/january-2026-dos-mitigation-async-hooks</a><p data-notion-block-id=\\"2f4e548d-8a8e-80d3-8a81-c5a27e8f44b0\\">Node.js AsyncLocalStorage\uc5d0\uc11c \uc624\ub958\uac00 \ubc1c\uc0dd\ud55c \uc774\uc720\ub97c \uc124\uba85\ud558\uace0, RSC\ub098 Next.js, APM\uc744 \uc0ac\uc6a9\ud558\uace0 \uc788\uc73c\uba74 \uc65c \uc5c5\ub370\uc774\ud2b8\ub97c \ud574\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2f1e548d-8a8e-809e-af95-c12a28691bf2\\" id=\\"2f1e548d-8a8e-809e-af95-c12a28691bf2\\">Nested \uc778\ud130\ub809\uc158(\uc911\ucca9\ub41c \ubc84\ud2bc \uc561\uc158)\uc740 \uc5b4\ub5bb\uac8c \ucc98\ub9ac\ud558\ub294\uac8c \uc88b\uc744\uae4c</h2><a href=\\"https://piccalil.li/blog/accessible-faux-nested-interactive-controls/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/accessible-faux-nested-interactive-controls/</a><h2 data-notion-block-id=\\"2f4e548d-8a8e-8036-aaf1-e50c27ad5c25\\" id=\\"2f4e548d-8a8e-8036-aaf1-e50c27ad5c25\\">Image to ASCII \ub80c\ub354\ub9c1 \ub525\ub2e4\uc774\ube0c</h2><a href=\\"https://alexharri.com/blog/ascii-rendering\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://alexharri.com/blog/ascii-rendering</a><h1 data-notion-block-id=\\"2f0e548d-8a8e-806c-a776-df58c2490075\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://blog.jquery.com/2026/01/17/jquery-4-0-0/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.jquery.com/2026/01/17/jquery-4-0-0/</a><p data-notion-block-id=\\"2f1e548d-8a8e-809f-bf75-d6066e4f6a88\\">jQuery 4.0\ubc84\uc804\uc774 \ub098\uc654\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/DoneDeal0/superdiff\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/DoneDeal0/superdiff</a><p data-notion-block-id=\\"2f4e548d-8a8e-80a7-92a4-f2cdb83aa66a\\">\ube60\ub974\uace0 \uc77d\uae30 \uc26c\uc6b4 diff \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4.</p><a href=\\"https://code.visualstudio.com/blogs/2026/01/15/docfind\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://code.visualstudio.com/blogs/2026/01/15/docfind</a><p data-notion-block-id=\\"2f4e548d-8a8e-8004-8b1c-fc1001aa89e9\\">Visual Studio Code\ud300\uc774 Rust/WASM\uc73c\ub85c \uc815\uc801 \uc0ac\uc774\ud2b8 \ud0a4\uc6cc\ub4dc \uac80\uc0c9\uc744 \uc5b4\ub5bb\uac8c \uad6c\ud604\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://github.com/microsoft/docfind\\">docfind</a>\ub85c  Github\uacf5\uac1c\ud588\uc73c\ub2c8 \uc815\uc801 \uc0ac\uc774\ud2b8\ub97c \uc81c\ud488\uc73c\ub85c \uac16\uace0\uc788\ub2e4\uba74 \uc0ac\uc6a9\ud574\ubcfc\ub9cc \ud560 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://blog.cloudflare.com/astro-joins-cloudflare/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/astro-joins-cloudflare/</a><p data-notion-block-id=\\"2f4e548d-8a8e-807a-8bbe-cf9a58c75da4\\">Astro\uac00 Cloudflare\uc5d0 \uc778\uc218\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p>"}')}}]);